tmCustomCss:
/* ================================================
   黑白漫画风 · Manga Mono Edition v1
   基于冰雪版改色 · 经典灰白漫画配色
   斜纹 / 网点 / 横线三种纹理组合
   ================================================ */

:root {
  --mono-black:  #2a2a2a;
  --mono-deep:   #1a1a1a;
  --mono-dark:   #000000;
  --mono-mid:    #666666;
  --mono-light:  #aaaaaa;
  --mono-pale:   #f0f0f0;
  --mono-white:  #ffffff;
  --mono-muted:  #888888;
}

/* ── 背景：浅灰底 + 网点 ── */
#this-moment-screen {
  background: #c8c8c8 !important;
}
.tm-bg-overlay {
  background:
    radial-gradient(circle, rgba(80,80,80,0.15) 1px, transparent 1px),
    radial-gradient(ellipse 200px 150px at  5% 10%, rgba(200,200,200,0.35) 0%, transparent 100%),
    radial-gradient(ellipse 240px 180px at 90% 15%, rgba(190,190,190,0.28) 0%, transparent 100%),
    radial-gradient(ellipse 180px 140px at 12% 65%, rgba(195,195,195,0.25) 0%, transparent 100%),
    radial-gradient(ellipse 220px 160px at 88% 80%, rgba(185,185,185,0.28) 0%, transparent 100%),
    linear-gradient(180deg, #ebebeb 0%, #d8d8d8 100%) !important;
  background-size:
    10px 10px,
    100% 100%, 100% 100%, 100% 100%, 100% 100%, 100% 100% !important;
}
.tm-bg-image {
  filter: blur(60px) saturate(0) brightness(1.1) !important;
}

/* ── 顶栏：深灰 + 斜纹 ── */
.tm-header {
  background:
    repeating-linear-gradient(
      -45deg,
      transparent, transparent 5px,
      rgba(255,255,255,0.25) 5px, rgba(255,255,255,0.25) 6px
    ),
    linear-gradient(180deg, #d0d0d0, #b8b8b8) !important;
  border-bottom: 2.5px solid #2a2a2a !important;
  min-height: 40px !important;
  padding: 4px 8px !important;
}
.tm-header-name {
  color: #1a1a1a !important;
  font-weight: 800 !important;
  font-size: 14px !important;
  letter-spacing: 0.5px !important;
  text-shadow: none !important;
}
.tm-top-vs {
  color: rgba(0,0,0,0.35) !important;
}
.tm-btn-icon {
  color: #2a2a2a !important;
  background: rgba(255,255,255,0.60) !important;
  border: 2px solid #2a2a2a !important;
  border-radius: 8px !important;
  width: 28px !important;
  height: 28px !important;
  box-shadow: 1.5px 1.5px 0 #2a2a2a !important;
}
.tm-btn-icon:hover {
  background: rgba(255,255,255,0.85) !important;
}
.tm-header-avatar {
  border: 2px solid #2a2a2a !important;
  border-radius: 50% !important;
  width: 22px !important;
  height: 22px !important;
}
.tm-top-drop-btn,
.tm-top-drop-btn-user {
  border-radius: 14px !important;
  padding: 2px 6px !important;
}

/* ── 故事区：网点底纹 ── */
.tm-story {
  padding: 10px 10px !important;
  background:
    radial-gradient(circle, rgba(80,80,80,0.15) 1px, transparent 1px),
    #f0f0f0 !important;
  background-size: 10px 10px, 100% 100% !important;
}
.tm-para {
  margin-bottom: 10px !important;
}

/* ── 正文字号 ── */
.tm-body-char {
  color: #1a1a1a !important;
  font-size: 17px !important;
  line-height: 2.0 !important;
  padding: 12px 14px !important;
  letter-spacing: 0.2px !important;
}
.tm-body-user {
  color: #1a1a1a !important;
  font-size: 17px !important;
  line-height: 1.9 !important;
  padding: 10px 14px !important;
  letter-spacing: 0.2px !important;
}

/* ── 角色消息卡片 ── */
.tm-para-char {
  background: #ffffff !important;
  border: 2.5px solid #2a2a2a !important;
  border-radius: 12px !important;
  box-shadow: 3px 3px 0 #2a2a2a !important;
  overflow: hidden !important;
  position: relative !important;
  isolation: isolate !important;
}

/* ── Header 骨架：斜纹 ── */
.tc-header-main {
  flex-direction: row !important;
  align-items: flex-start !important;
  gap: 8px !important;
  padding: 8px 10px 6px !important;
  background:
    repeating-linear-gradient(
      -45deg,
      transparent, transparent 4px,
      rgba(0,0,0,0.05) 4px, rgba(0,0,0,0.05) 5px
    ),
    rgba(80,80,80,0.08) !important;
  border-bottom: 1.5px dashed #aaaaaa !important;
}
.tc-avatar-area {
  flex-direction: column !important;
  align-items: center !important;
  flex-shrink: 0 !important;
}
.tc-avatar-frame {
  width: 58px !important;
  height: 58px !important;
  border-radius: 10px !important;
  border: 2px solid #2a2a2a !important;
  box-shadow: 2px 2px 0 #2a2a2a !important;
  background: #e0e0e0 !important;
}
.tc-avatar-img {
  border-radius: 8px !important;
  object-fit: cover !important;
}
.tc-avatar-badge {
  font-size: 9px !important;
  letter-spacing: 1.5px !important;
  color: #888888 !important;
  margin-top: 3px !important;
}
.tc-meta-area {
  gap: 3px !important;
}
.tc-meta-title {
  font-size: 17px !important;
  font-weight: 900 !important;
  color: #1a1a1a !important;
  letter-spacing: 0.5px !important;
  line-height: 1.2 !important;
}
.tc-meta-subtitle {
  min-height: 12px !important;
}
.tc-meta-subtitle::before {
  content: 'MANGA STYLE · SPECIAL EDITION';
  font-size: 9px !important;
  letter-spacing: 1.5px !important;
  color: #888888 !important;
}
.tc-meta-stats {
  gap: 3px !important;
  flex-wrap: wrap !important;
}
.tc-stat {
  background: #f5f5f5 !important;
  color: #333333 !important;
  border: 1.5px solid #2a2a2a !important;
  border-radius: 0 !important;
  font-weight: 700 !important;
  font-size: 10px !important;
  padding: 1px 6px !important;
  box-shadow: 1px 1px 0 #2a2a2a !important;
}
.tc-stat[data-label="page"]::before  { content: 'A · '; }
.tc-stat[data-label="words"]::before { content: 'B · '; }
.tc-stat[data-label="date"]::before  { content: '© '; }

.tc-divider {
  border-color: #cccccc !important;
  border-top-width: 1.5px !important;
  border-style: solid !important;
  margin: 0 10px !important;
}
.tc-divider-text::before {
  content: '★ COMIC MESSAGE ★';
  font-size: 9px !important;
  letter-spacing: 2px !important;
  color: #999999 !important;
}

/* Header 顶部装饰条：斜纹 */
.tc-deco-top {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  height: 20px !important;
  background:
    repeating-linear-gradient(
      -45deg,
      transparent, transparent 5px,
      rgba(255,255,255,0.10) 5px, rgba(255,255,255,0.10) 6px
    ),
    #2a2a2a !important;
  border-bottom: 1.5px solid #1a1a1a !important;
}
.tc-deco-top::after {
  content: '★  MANGA SPECIAL  ★  ✦' !important;
  font-size: 9px !important;
  letter-spacing: 2px !important;
  color: rgba(255,255,255,0.88) !important;
}

/* ── 文字格式 ── */
.tm-bold {
  color: #1a1a1a !important;
  font-weight: 900 !important;
  background: rgba(0,0,0,0.08) !important;
  padding: 0 2px !important;
}
.tm-action {
  color: #666666 !important;
  font-style: italic !important;
}
.tm-del { color: #aaaaaa !important; }
.tm-quote-block {
  border-left: 3px solid #aaaaaa !important;
  background: rgba(0,0,0,0.04) !important;
  border-radius: 0 8px 8px 0 !important;
  padding: 8px 12px !important;
  font-size: 17px !important;
  line-height: 2.0 !important;
}

/* ── 用户消息：横线稿纸 ── */
.tm-para-user {
  background:
    repeating-linear-gradient(
      0deg,
      transparent, transparent 9px,
      rgba(0,0,0,0.05) 9px, rgba(0,0,0,0.05) 10px
    ),
    #e8e8e8 !important;
  border: 2px dashed #2a2a2a !important;
  border-radius: 12px 12px 4px 12px !important;
  box-shadow: 2px 2px 0 #aaaaaa !important;
}

/* ── 输入区：深灰 + 斜纹 ── */
.tm-compose {
  background:
    repeating-linear-gradient(
      -45deg,
      transparent, transparent 5px,
      rgba(255,255,255,0.08) 5px, rgba(255,255,255,0.08) 6px
    ),
    linear-gradient(180deg, #4a4a4a, #2a2a2a) !important;
  border-top: 2.5px solid #1a1a1a !important;
}
.tm-compose::after {
  display: none !important;
}
.tm-compose-toolbar {
  padding: 5px 8px 4px !important;
  border-bottom: 1.5px dashed rgba(255,255,255,0.25) !important;
  gap: 5px !important;
  min-height: unset !important;
}

/* ── 工具栏按钮基础 ── */
.tm-regen-btn,
.tm-suggestions-btn {
  width: 30px !important;
  height: 30px !important;
  border: 2px solid rgba(255,255,255,0.50) !important;
  border-radius: 8px !important;
  background: rgba(255,255,255,0.15) !important;
  box-shadow: 1.5px 1.5px 0 #1a1a1a !important;
  color: #ffffff !important;
  flex-shrink: 0 !important;
}
.tm-regen-btn:hover,
.tm-suggestions-btn:hover {
  background: rgba(255,255,255,0.28) !important;
}

/* 重投 · 冷蓝（唯一彩色点缀） */
.tm-compose-toolbar > .tm-regen-btn:nth-of-type(1) {
  color: #c0d8f8 !important;
  border-color: #88b0e0 !important;
  background: rgba(136,176,224,0.22) !important;
  box-shadow: 1.5px 1.5px 0 #1a1a1a !important;
}
/* 继续剧情 · 浅绿 */
.tm-compose-toolbar > .tm-regen-btn:nth-of-type(2) {
  color: #a8e8c0 !important;
  border-color: #70c090 !important;
  background: rgba(112,192,144,0.20) !important;
  box-shadow: 1.5px 1.5px 0 #1a1a1a !important;
}
/* 白噪音 · 浅金 */
.tm-compose-toolbar > .tm-regen-btn:nth-of-type(3) {
  color: #f8e080 !important;
  border-color: #d0b840 !important;
  background: rgba(208,184,64,0.20) !important;
  box-shadow: 1.5px 1.5px 0 #1a1a1a !important;
}
/* 拍照 · 浅粉 */
.tm-compose-toolbar > .tm-regen-btn:nth-of-type(4) {
  color: #f0c0e0 !important;
  border-color: #c890b8 !important;
  background: rgba(200,144,184,0.20) !important;
  box-shadow: 1.5px 1.5px 0 #1a1a1a !important;
}
/* 完结故事 · 纯黑反白 */
.tm-compose-toolbar > .tm-regen-btn:nth-of-type(5) {
  background: #000000 !important;
  color: #f0f0f0 !important;
  border-color: #000000 !important;
  box-shadow: 1.5px 1.5px 0 #444444 !important;
}
/* 建议回复 · 星形虚线 */
.tm-suggestions-btn {
  background: rgba(255,255,255,0.15) !important;
  color: #f0f0f0 !important;
  border-style: dashed !important;
  border-color: rgba(255,255,255,0.60) !important;
  box-shadow: 1.5px 1.5px 0 #1a1a1a !important;
  font-size: 0 !important;
  overflow: hidden !important;
  position: relative !important;
}
.tm-suggestions-btn::after {
  content: '★' !important;
  font-size: 13px !important;
  color: #f0f0f0 !important;
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
}
.tm-suggestions-chevron {
  display: none !important;
}
/* 白噪音激活态 */
.tm-regen-btn.active {
  background: rgba(255,255,255,0.32) !important;
  color: #ffffff !important;
  border-color: rgba(255,255,255,0.80) !important;
  box-shadow: 1.5px 1.5px 0 #1a1a1a !important;
}

/* ── 输入行 ── */
.tm-compose-row {
  padding: 5px 8px 6px !important;
}
.tm-input {
  background: rgba(255,255,255,0.18) !important;
  color: #ffffff !important;
  border: 2px solid rgba(255,255,255,0.50) !important;
  border-radius: 16px !important;
  box-shadow: 2px 2px 0 #1a1a1a !important;
  font-size: 14px !important;
  padding: 7px 14px !important;
  min-height: unset !important;
}
.tm-input::placeholder {
  color: rgba(255,255,255,0.45) !important;
  font-size: 13px !important;
}
.tm-input:focus {
  border-color: rgba(255,255,255,0.85) !important;
  box-shadow: 3px 3px 0 #000000 !important;
}
.tm-send-btn {
  background: #000000 !important;
  color: #f0f0f0 !important;
  border: 2px solid rgba(255,255,255,0.8) !important;
  border-radius: 50% !important;
  width: 34px !important;
  height: 34px !important;
  box-shadow: 2px 2px 0 #1a1a1a !important;
  flex-shrink: 0 !important;
}
.tm-send-btn.ready {
  background: #000000 !important;
  color: #f0f0f0 !important;
}

/* ── 滚动条 ── */
.tm-story::-webkit-scrollbar { width: 3px !important; }
.tm-story::-webkit-scrollbar-thumb {
  background: #aaaaaa !important;
  border-radius: 3px !important;
}
.tm-story::-webkit-scrollbar-track { background: transparent !important; }

/* ── 悬停动效 ── */
.tm-para-char, .tm-para-user {
  transition: transform 0.2s ease, box-shadow 0.2s ease !important;
}
.tm-para-char:hover {
  transform: translateY(-2px) !important;
  box-shadow: 5px 5px 0 #2a2a2a !important;
}
.tm-para-user:hover { transform: translateY(-1px) !important; }

/* ── 进场动画 ── */
#this-moment-screen:not(.tm-no-animations) .tm-para-block {
  animation: monoFadeIn 0.4s cubic-bezier(0.2,0.8,0.3,1) forwards !important;
}
@keyframes monoFadeIn {
  from { opacity: 0; transform: translateY(6px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0)   scale(1); }
}

/* ── 长按菜单 ── */
.tm-context-menu {
  background: #f5f5f5 !important;
  border: 2px solid #2a2a2a !important;
  border-radius: 10px !important;
  box-shadow: 3px 3px 0 #2a2a2a !important;
}
.tm-context-menu button { color: #1a1a1a !important; }
.tm-ctx-delete { color: #cc3333 !important; }
